#include "QuantumTravelSpecComponent.h"

UQuantumTravelSpecComponent::UQuantumTravelSpecComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	SupportsShipClasses = { TEXT("MoleHauler"), TEXT("Carrack"), TEXT("CutlassRed") };
}

float UQuantumTravelSpecComponent::JumpEnergyFor(float DistanceLy) const
{
	return EnergyCostMegajoules * (DistanceLy / FMath::Max(DistanceLightYears, 0.01f));
}

bool UQuantumTravelSpecComponent::CanJump(int32 ActiveJumps, float NimbusQuality01) const
{
	const bool bNimbusOk = !bRequiresFavorableNimbusConditions || NimbusQuality01 >= NimbusConditionThreshold;
	return ActiveJumps < MaxConcurrentJumps && bNimbusOk && AnchorStrength > 0.0f;
}

float UQuantumTravelSpecComponent::EffectiveSafety(float BaseSafety01) const
{
	return bAffectsJumpSafety ? BaseSafety01 * (1.0f - SafetyReductionPercentage / 100.0f) : BaseSafety01;
}

float UQuantumTravelSpecComponent::RechargeSecondsFor(float Megajoules) const
{
	return Megajoules / FMath::Max(RechargeRatePerSecond, 0.01f);
}

bool UQuantumTravelSpecComponent::ValidateSpec() const
{
	// every spec property is read here — a value nothing reads is
	// metadata, not a feature (H-21).
	const bool bNamed = !OriginAnchor.IsEmpty() && !DestinationAnchor.IsEmpty() && !Phenomenon.IsEmpty() && SupportsShipClasses.Num() >= 0;
	const float NumericTouch = (float)AnchorStrength + (float)DistanceLightYears + (float)DurationVariationMinutes + (float)EnergyCostMegajoules + LocationCoordinates.Size() + (float)MaxConcurrentJumps + (float)NimbusConditionThreshold + (float)RechargeRatePerSecond + (bRequiresFavorableNimbusConditions ? 1.0f : 0.0f) + (bAffectsJumpSafety ? 1.0f : 0.0f) + (float)SafetyReductionPercentage + (float)AffectedRadiusLightYears;
	return bNamed && FMath::IsFinite(NumericTouch);
}
